// ── the GitHub tab ──
// The same dispatches the panel makes, so a run started here is a run the
// panel recognises. Sessions are read from the branch over raw (no token
// quota), and every action answers on screen instead of leaving a button grey
// with no explanation.
const SLOT_OF_RUN = {
  '.github/workflows/hub.yml': 'hub-linux',
  '.github/workflows/agent.yml': 'agent-linux',
  '.github/workflows/opencode.yml': 'opencode-linux',
  '.github/workflows/desks.yml': 'windows'
};
const NAME_OF_RUN = {
  '.github/workflows/hub.yml': 'NPM Hub',
  '.github/workflows/agent.yml': 'CLI-агент',
  '.github/workflows/opencode.yml': 'OpenCode',
  '.github/workflows/desks.yml': 'Столы'
};
const START_OF_RUN = {
  '.github/workflows/hub.yml': 'hub.yml',
  '.github/workflows/agent.yml': 'agent.yml',
  '.github/workflows/opencode.yml': 'opencode.yml',
  '.github/workflows/desks.yml': 'desks.yml'
};
async function readSlotRaw(slot) {
  for (const path of ['live/session-' + slot + '.json', 'session-' + slot + '.json']) {
    try {
      const r = await fetch(`https://raw.githubusercontent.com/${REPO}/session-state/${path}?t=${Date.now()}`,
        { cache: 'no-store' });
      if (r.ok) return JSON.parse(await r.text());
    } catch (e) { /* try the next name */ }
  }
  return null;
}
// Формат времени для журнала и карточек: 3:02:01 или 42:17.
function fmtClock(sec) {
  sec = Math.max(0, Math.floor(sec));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), ss = sec % 60;
  return (h ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
}
// Живой счётчик на карточках активных сессий: тикает раз в 15 с,
// чтобы «кто-то закрывает» сразу было видно по возрасту из 6:00:00.
setInterval(() => {
  document.querySelectorAll('#gh-sessions .meta[data-c]').forEach(el => {
    const created = new Date(el.dataset.c).getTime();
    if (!created) return;
    const num = (el.textContent.match(/#(\d+)/) || [])[1] || '?';
    el.textContent = '#' + num + ' · идёт ' + fmtClock(Math.floor((Date.now() - created) / 1000)) + ' из 6:00:00';
  });
}, 15000);
function minsAgo(iso) {
  const t = Date.parse(iso || '');
  if (!Number.isFinite(t)) return '';
  const m = Math.max(0, Math.round((Date.now() - t) / 60000));
  return m < 1 ? 'только что' : (m + ' мин назад');
}
function runStatusPill(run) {
  if (!run) return '<span class="pill">—</span>';
  if (run.status === 'completed') {
    const ok = run.conclusion === 'success';
    return '<span class="pill ' + (ok ? 'live' : 'queue') + '">' +
      (ok ? 'успешно' : (run.conclusion || 'завершён')) + '</span>';
  }
  return '<span class="pill queue">' + (RUN_STAGE[run.status] || run.status) + '</span>';
}
function tokenNow() { return ($('token').value || '').trim(); }
function needToken(btn) {
  if (tokenNow()) return true;
  if (btn) busy(btn, true, 'Нужен токен');
  log('Вставьте GitHub-токен на вкладке «Хаб».', 'err');
  progStart('Нужен токен', { cancellable: false });
  progFinish(false, 'Вставьте GitHub-токен на вкладке «Хаб».');
  if (btn) busy(btn, false);
  return false;
}
async function ghRefresh() {
  const token = tokenNow();
  const box = $('gh-sessions');
  if (!token) { box.innerHTML = '<div class="muted">Вставьте GitHub-токен на вкладке «Хаб».</div>'; return; }
  box.innerHTML = '<div class="muted">Загружаю…</div>';
  const runs = $('gh-runs');
  runs.innerHTML = '<div class="muted">Загружаю…</div>';
  try {
    const active = await listActiveRuns(token, isSessionRun);
    // Кеш для openSlot: «сессия завершена» в файле почти всегда означает
    // «файл от прошлого запуска, новый ещё раскладывается» — отличаем по
    // активному рану из этого списка.
    try { window.__ghActiveRuns = active; window.__ghActiveRunsAt = Date.now(); } catch (e) {}
    if (!active.length) {
      box.innerHTML = '<div class="muted">Активных сессий нет.</div>';
    } else {
      box.innerHTML = active.map(r => {
        const slot = SLOT_OF_RUN[r.path] || '';
        const nm = NAME_OF_RUN[r.path] || r.name || 'сессия';
        return `<div class="row" data-run="${r.id}" data-slot="${esc(slot)}">
          <div class="top"><span class="nm">${esc(nm)}</span>${runStatusPill(r)}</div>
          <div class="meta" data-c="${esc(r.created_at)}">#${r.run_number} · идёт ${fmtClock(Math.floor((Date.now() - new Date(r.created_at).getTime()) / 1000))} из 6:00:00</div>
          <div class="acts">
            ${slot ? '<button class="ghost" data-act="open">Открыть</button>' : ''}
            <button class="ghost" data-act="stop">Остановить</button>
          </div>
        </div>`;
      }).join('');
      for (const row of box.querySelectorAll('.row')) wireRunRow(row, token);
    }
    const recent = await api(`/repos/${REPO}/actions/runs?per_page=12`, token);
    const list = ((recent && recent.workflow_runs) || [])
      .filter(r => SESSION_WORKFLOWS.has(r.path) || /APK|Tests|Build|Syntax/.test(r.name || ''));
    runs.innerHTML = list.length ? list.map(r => {
      let tail = '';
      if (r.status === 'completed' || r.conclusion) {
        const dmin = Math.round((new Date(r.updated_at).getTime() - new Date(r.created_at).getTime()) / 60000);
        tail = ' · ' + (r.conclusion === 'cancelled'
          ? (dmin >= 350 ? 'легла по лимиту 6 ч' : 'остановлена')
          : (r.conclusion === 'success' ? 'завершена ok' : (r.conclusion || '—')));
      } else {
        tail = ' · идёт ' + fmtClock(Math.floor((Date.now() - new Date(r.created_at).getTime()) / 1000));
      }
      return `<div class="row">
        <div class="top"><span class="nm">${esc(r.name || 'workflow')}</span>${runStatusPill(r)}</div>
        <div class="meta">#${r.run_number} · ${esc(minsAgo(r.created_at))}${tail}</div>
      </div>`;
    }).join('') : '<div class="muted">Пусто.</div>';
  } catch (e) {
    const msg = (e && e.message) || String(e);
    box.innerHTML = '<div class="muted">Не загрузилось: ' + esc(msg) + '</div>';
    runs.innerHTML = '<div class="muted">—</div>';
    log('Список сессий: ' + msg, 'err');
  }
}
function wireRunRow(row, token) {
  const id = row.dataset.run;
  const slot = row.dataset.slot;
  const acts = row.querySelectorAll('button[data-act]');
  for (const b of acts) {
    b.onclick = async () => {
      const act = b.dataset.act;
      if (act === 'stop') {
        if (!confirm('Остановить этот запуск?')) return;
        busy(b, true, 'Останавливаю…');
        const p = progStart('Остановка запуска #' + id);
        progT0 = p.startedAt; progFill();
        try {
          await api(`/repos/${REPO}/actions/runs/${id}/cancel`, token, { method: 'POST' });
          log('Запрошена остановка #' + id + '. Жду, пока GitHub закроет…', 'ok');
          const done = await waitForRunsToStop(token, [id], 3000, 40);
          progFinish(true, 'Запуск #' + id + ' остановлен.');
          log('Запуск #' + id + ' остановлен.', 'ok');
          if (done) await ghRefresh();
        } catch (e) {
          const msg = (e && e.message) || String(e);
          log('Остановка: ' + msg, 'err');
          progFinish(false, msg);
        } finally {
          busy(b, false);
        }
        return;
      }
      if (act === 'open') { await openSlot(slot, b); return; }
    };
  }
}
async function openSlot(slot, btn) {
  if (btn) busy(btn, true, 'Открываю…');
  try {
    const s = await readSlotRaw(slot);
    if (!s || s.state !== 'live' || !(s.hubUrl || s.agentUrl || s.url || s.deskUrl)) {
      let why = !s ? 'сессия не опубликована'
        : (s.state === 'ended' ? 'сессия завершена' : 'адрес ещё не опубликован');
      // Файл «завершена» — от предыдущего запуска: если список сессий минуту
      // назад видел ИДУЩИЙ ран этого слота, хаб просто ещё загружается
      // (репозитории/VNC — это минуты), а не «завершён».
      const cachedRuns = window.__ghActiveRuns;
      const cachedAt = window.__ghActiveRunsAt || 0;
      if (s && s.state === 'ended') {
        // 60-сек кэша мало: если вкладка не обновлялась минуту, слот «завершён»
        // прошлого рана подменяет «новый ран ещё раскатывается» — и кнопка
        // «Открыть» врёт «сессия завершена». Один свежий запрос — и правда на месте.
        let runs = (cachedRuns && (Date.now() - cachedAt) < 60000) ? cachedRuns : null;
        if (!runs) {
          try {
            runs = await listActiveRuns(tokenNow(), isSessionRun);
            window.__ghActiveRuns = runs; window.__ghActiveRunsAt = Date.now();
          } catch (e) { runs = cachedRuns; }
        }
        const run = runs && runs.find(r => isHubRun(r) || (typeof SLOT_OF_RUN !== 'undefined' && SLOT_OF_RUN[r.path] === slot));
        if (run) {
          // Ран жив — значит «завершена» просто старый файл. Не отправляем
          // пользователя жать «Открыть» вслепую: ждём адрес тут, с часами.
          const t0 = Date.now();
          const started = new Date(run.created_at).getTime();
          try { window.stopWaiting = false; } catch (e) {}
          log('Хаб ещё поднимается (ран #' + run.run_number + ', идёт '
            + fmtClock(Math.floor((t0 - started) / 1000)) + '). Жду адрес сам…', '');
          progStart('Жду адрес хаба (ран #' + run.run_number + ')', { cancellable: true });
          progT0 = t0; progFill();
          const tick = setInterval(() => {
            log('…жду адрес: ' + fmtClock(Math.floor((Date.now() - t0) / 1000))
              + ' (ран #' + run.run_number + ' идёт ' + fmtClock(Math.floor((Date.now() - started) / 1000)) + ')', '');
          }, 20000);
          let s2 = null;
          try { s2 = await waitForHub(tokenNow(), t0, 5000, () => stopWaiting, run.id); }
          catch (e) { log('Ожидание адреса: ' + (e && e.message || e), 'err'); }
          clearInterval(tick);
          if (s2 && s2.state === 'live') {
            log('Адрес готов за ' + fmtClock(Math.floor((Date.now() - t0) / 1000)) + '. Открываю…', 'ok');
            progFinish(true, 'Адрес готов. Открываю…');
            return openSlot(slot, btn);
          }
          why = 'ждал ' + Math.max(1, Math.round((Date.now() - t0) / 60000))
            + ' мин — адрес не появился (ран, возможно, умер). Жми «Остановить и перезапустить ранер»';
        }
      }
      log('Открыть нельзя: ' + why + '.', 'err');
      progStart('Не открывается', { cancellable: false });
      progFinish(false, why + '.');
      return;
    }
    if (slot === 'hub-linux') {
      // A hub is gated: the token that opened it has to be the one the launch
      // used, or it answers 401 to a page that looks perfectly fine. Main
      // address first, warm reserve (url2) second; the launch token, the last
      // connected token and the spare entrance (from the GitHub token) are all
      // tried, in that order.
      const { list: candidates, spare } = await hubCandidates(s);
      const bases = sessionBases(s);
      const probe = await firstReachableBase(bases, candidates, s.runId);
      if (!probe.base) throw describeBaseFailure(bases, probe.errors, candidates[candidates.length - 1] || '', !!spare);
      const got = probe.base;
      const viaSpare = !!(spare && probe.zt === spare);
      saveLast(buildOpenUrl(s, probe.zt, got), bases.filter(b => b !== got)[0] || '');
      if (viaSpare) log('Запасной вход: вошёл по коду из GitHub-токена.', 'ok');
      else if (bases.indexOf(got) > 0) log('Перешёл на резервный адрес.', 'ok');
      location.href = buildOpenUrl(s, probe.zt, got);
      return;
    }
    const base = String(s.hubUrl || s.agentUrl || s.url || s.deskUrl).replace(/\/+$/, '');
    const zt = lastOriginToken().zt;
    location.href = zt ? (base + (base.includes('?') ? '&' : '?') + 'zt=' + encodeURIComponent(zt)) : base;
  } catch (e) {
    let msg = (e && e.message) || String(e);
    // Голое «Failed to fetch» ни о чём не говорит: обычно это мёртвый туннель
    // от прошлого запуска, поэтому подсказываем живые кнопки.
    if (/failed to fetch|networkerror|load failed|err_internet|err_connection/i.test(msg)) {
      msg = 'Адрес не отвечает — адрес прошлого запуска уже мёртв. Если хаб жив — «Запустить хаб» подберёт доступ, иначе жми «Остановить и перезапустить ранер».';
    }
    log('Открыть не вышло: ' + msg, 'err');
    progStart('Не открывается', { cancellable: false });
    progFinish(false, msg);
  } finally {
    if (btn) busy(btn, false);
  }
}
// Start anything from the panel's own button set, and narrate it.
async function startSession(file, inputs, btn, label) {
  if (!needToken(btn)) return;
  busy(btn, true, 'Отправляю…');
  stopWaiting = false;
  const p = progStart(label);
  progT0 = p.startedAt; progFill();
  const since = Date.now();
  try {
    await dispatchWorkflow(tokenNow(), file, inputs);
    log(label + ': запрос отправлен.', 'ok');
    const run = await findFreshRun(tokenNow(), since, null);
    if (run) logStep('Прогон #' + run.run_number + ' — ' + (RUN_STAGE[run.status] || run.status));
    progStage('Жду завершения…');
    const end = await followRun(tokenNow(), run ? run.id : 0, { attempts: 90, untilLive: true });
    if (!end) {
      if (stopWaiting) { progFinish(false, 'Ожидание прервано.'); return; }
      throw new Error('Прогон не найден в списке GitHub.');
    }
    if (end.conclusion === 'success') {
      progFinish(true, label + ' — успешно.');
      log(label + ' завершён успешно.', 'ok');
    } else {
      progFinish(false, label + ' — ' + (end.conclusion || 'с ошибкой'));
      log(label + ' завершён: ' + (end.conclusion || 'с ошибкой'), 'err');
    }
    await ghRefresh();
  } catch (e) {
    const msg = (e && e.message) || String(e);
    log(label + ': ' + msg, 'err');
    progFinish(false, msg);
  } finally {
    busy(btn, false);
  }
}
