  startSession('hub.yml', inputs, $('run-hub'), 'NPM Hub');
};
$('wf-panel-apk').onclick = () => startSession('panel-apk.yml', {}, $('wf-panel-apk'), 'Сборка APK панели');
$('wf-hub-apk').onclick = () => startSession('hub-apk.yml', {}, $('wf-hub-apk'), 'Сборка APK хаба');
$('wf-build').onclick = () => startSession('build-win.yml', {}, $('wf-build'), 'Сборка Windows');
$('wf-tests').onclick = () => startSession('tests.yml', {}, $('wf-tests'), 'Тесты');
// A dispatch whose connect got interrupted (reload, crash): try to open it.
(function autoPending() {
  const p = readPending();
  if (!p) return;
  if (Date.now() - (p.since || 0) > 30 * 60 * 1000) return;
  if (last && last.url && Date.now() - (last.at || 0) <= 30 * 60 * 1000) return;
  const t2 = ($('token').value || '').trim();
  if (!t2) return;
  log('Есть незавершённый запуск — проверяю, жив ли он…');
  tryOpenLive(t2);
})();
</script>
