// Walk the candidate addresses (main first, then the warm reserve) and return
// the first that accepts one of our tokens, together with WHY every earlier
// one failed. Accepts a single token (string) or a list of candidates (array,
// best first - see hubCandidates). The old code threw the same blanket
// «Ни основной, ни резервный адрес не отвечает» no matter what happened, and
// printed it even when the reserve had never been published and only one
// address existed - which turned a plain 401 (missing launch token) into a
// phantom network outage.
async function firstReachableBase(bases, ztOrCandidates, runId) {
  const candidates = Array.isArray(ztOrCandidates) ? ztOrCandidates : [ztOrCandidates];
  const errors = [];
  for (let i = 0; i < bases.length; i++) {
    if (i > 0) log('Основной адрес молчит — пробую резервный…');
