  busy(btn, true, 'Отправляю…');
  stopWaiting = false;
  const p = progStart(kind === 'restart' ? 'Перезапуск раннера' : 'Запуск хаба');
  progT0 = p.startedAt;
  progFill();
  try {
    if (kind === 'restart') {
      progStage('Проверяю, не занял ли кто-то раннер…');
      const active = await listActiveRuns(token, isSessionRun);
      if (active.some(run => !isHubRun(run))) {
        throw new Error('Другая сессия уже использует раннер. Остановите её перед перезапуском NPM Hub.');
