   const el = $('log');
   if (!el) return;
   const line = document.createElement('div');
   if (cls) line.className = cls;
   const ts = document.createElement('span');
   ts.className = 'ts';
   ts.textContent = hhmmss(new Date());
   line.appendChild(ts);
   line.appendChild(document.createTextNode(String(m == null ? '' : m)));
   el.appendChild(line);
   while (el.childElementCount > LOG_MAX) el.removeChild(el.firstChild);
