   el.style.display = '';
   $('prog-label').textContent = label;
   $('prog-stage').textContent = o.stage || 'Отправляю запрос…';
   $('prog-time').textContent = '0:00';
   $('prog-fill').style.width = '4%';
   $('prog-act').style.display = o.cancellable === false ? 'none' : '';
