   const el = $('prog');
   if (progTimer) { clearInterval(progTimer); progTimer = null; }
   if (progAbort) { progAbort = null; }
   el.className = 'prog ' + (ok ? 'done' : 'fail');
   $('prog-fill').style.width = '100%';
   if (text) progStage(text);
   $('prog-act').style.display = 'none';
   setTimeout(() => { if (el.className.indexOf('fail') >= 0) el.style.display = 'none'; }, 6000);
