   if (!btn) return;
   if (on) {
     if (!busyLabels.has(btn)) busyLabels.set(btn, btn.textContent);
     btn.disabled = true;
     btn.dataset.busy = '1';
     if (text) btn.textContent = text;
   } else {
     btn.disabled = false;
