 const STEP_RU = {
   'Set up job': 'подготовка',
   'Run actions/checkout@v4': 'получение кода',
   'Mask the gate token in logs': 'маскирование токена',
   'Run actions/setup-node@v4': 'установка Node',
   'Restore the npm/pip caches': 'кэш пакетов',
   'Install the CLI agents': 'установка агентов',
   'Install the hub dependencies': 'зависимости хаба',
   'Install OpenCode for session recovery': 'установка OpenCode',
   'Put zen-agent on PATH': 'установка zen-agent',
   'Create the work folder and restore repositories': 'восстановление репозиториев',
   'Start the hub and open the tunnel': 'запуск хаба и туннеля',
   'Keep the session alive': 'сессия работает',
   'Keep the VNC session alive': 'VNC работает',
   'Start the Linux desktop and open the tunnel': 'запуск рабочего стола',
   'Install the desktop + VNC stack': 'установка рабочего стола',
   'Final durable repository and session backup': 'финальное сохранение',
   'Clear the published session': 'снятие публикации',
   'Snapshot audit/code on exit': 'снимок кода и чата',
   'Save the models snapshot': 'снимок моделей',
   'Record the run in the history': 'запись в историю',
   'Build release APK': 'сборка APK',
   'Package APK': 'упаковка APK',
   'Publish GitHub Release': 'публикация релиза',
   'Restore repositories': 'восстановление репозиториев'
